const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define regions: East Midlands, northeast England, and eastern Scotland
  const eastMidlands = ee.Geometry.Polygon([
    [[-1.5, 52.5], [0.5, 52.5], [0.5, 53.5], [-1.5, 53.5], [-1.5, 52.5]]
  ]);

  const northeastEngland = ee.Geometry.Polygon([
    [[-2.5, 54.5], [-1.0, 54.5], [-1.0, 55.5], [-2.5, 55.5], [-2.5, 54.5]]
  ]);

  const easternScotland = ee.Geometry.Polygon([
    [[-4.0, 56.0], [-2.0, 56.0], [-2.0, 57.5], [-4.0, 57.5], [-4.0, 56.0]]
  ]);

  const regions = ee.FeatureCollection([
    ee.Feature(eastMidlands, {name: 'East Midlands'}),
    ee.Feature(northeastEngland, {name: 'Northeast England'}),
    ee.Feature(easternScotland, {name: 'Eastern Scotland'})
  ]);

  const combinedRegion = eastMidlands.union(northeastEngland).union(easternScotland);

  // Get daily precipitation data for specific dates
  const oct2023 = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
    .filterDate('2023-10-01', '2023-10-02')
    .select('total_precipitation_sum')
    .first();

  const jan2024 = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
    .filterDate('2024-01-04', '2024-01-05')
    .select('total_precipitation_sum')
    .first();

  // Check if data exists
  const oct2023Exists = await new Promise((resolve) => {
    ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
      .filterDate('2023-10-01', '2023-10-02')
      .size()
      .evaluate((size) => resolve(size > 0));
  });

  const jan2024Exists = await new Promise((resolve) => {
    ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
      .filterDate('2024-01-04', '2024-01-05')
      .size()
      .evaluate((size) => resolve(size > 0));
  });

  if (!oct2023Exists || !jan2024Exists) {
    console.log('Missing data for 2023/2024 dates');
    console.log('<answer>C1</answer>');
    return;
  }

  // Calculate mean precipitation for 2023/2024
  const oct2023Mean = await new Promise((resolve, reject) => {
    oct2023.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: combinedRegion,
      scale: 11132,
      maxPixels: 1e9
    }).evaluate((result, error) => {
      if (error) reject(error);
      else resolve(result.total_precipitation_sum);
    });
  });

  const jan2024Mean = await new Promise((resolve, reject) => {
    jan2024.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: combinedRegion,
      scale: 11132,
      maxPixels: 1e9
    }).evaluate((result, error) => {
      if (error) reject(error);
      else resolve(result.total_precipitation_sum);
    });
  });

  // Get climatology for October (1991-2020)
  const octClimatology = ee.ImageCollection('ECMWF/ERA5_LAND/MONTHLY_AGGR')
    .filter(ee.Filter.calendarRange(1991, 2020, 'year'))
    .filter(ee.Filter.calendarRange(10, 10, 'month'))
    .select('total_precipitation_sum')
    .mean();

  // Get climatology for January (1991-2020)
  const janClimatology = ee.ImageCollection('ECMWF/ERA5_LAND/MONTHLY_AGGR')
    .filter(ee.Filter.calendarRange(1991, 2020, 'year'))
    .filter(ee.Filter.calendarRange(1, 1, 'month'))
    .select('total_precipitation_sum')
    .mean();

  const octClimoMean = await new Promise((resolve, reject) => {
    octClimatology.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: combinedRegion,
      scale: 11132,
      maxPixels: 1e9
    }).evaluate((result, error) => {
      if (error) reject(error);
      else resolve(result.total_precipitation_sum);
    });
  });

  const janClimoMean = await new Promise((resolve, reject) => {
    janClimatology.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: combinedRegion,
      scale: 11132,
      maxPixels: 1e9
    }).evaluate((result, error) => {
      if (error) reject(error);
      else resolve(result.total_precipitation_sum);
    });
  });

  // Validate results
  if (oct2023Mean === null || jan2024Mean === null || octClimoMean === null || janClimoMean === null) {
    console.log('Calculation returned null values');
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert to mm for readability (ERA5 is in meters)
  console.log(`Oct 1, 2023 rainfall: ${(oct2023Mean * 1000).toFixed(2)} mm`);
  console.log(`Oct 1991-2020 avg daily: ${(octClimoMean / 31 * 1000).toFixed(2)} mm`);
  console.log(`Jan 4, 2024 rainfall: ${(jan2024Mean * 1000).toFixed(2)} mm`);
  console.log(`Jan 1991-2020 avg daily: ${(janClimoMean / 31 * 1000).toFixed(2)} mm`);

  // Compare: daily values vs. climatological daily average
  const octHigher = oct2023Mean > (octClimoMean / 31);
  const janHigher = jan2024Mean > (janClimoMean / 31);

  console.log(`October comparison: ${octHigher ? 'Higher' : 'Lower or equal'}`);
  console.log(`January comparison: ${janHigher ? 'Higher' : 'Lower or equal'}`);

  if (octHigher && janHigher) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
